const candResp = $('Find Nudge Candidates').first().json;
const winResp = $('Load Send Windows').first().json;
const leads = (candResp && Array.isArray(candResp.body)) ? candResp.body : [];
const windows = (winResp && Array.isArray(winResp.body)) ? winResp.body : [];

const byCountry = {};
windows.forEach(function (w) { byCountry[w.country_code] = w; });

// Same default as 01's Resolve Send Context: an unseeded country falls back to AE.
const DEFAULT = byCountry['AE'] || { timezone: 'Asia/Dubai', quiet_hours_start: '22:00:00', quiet_hours_end: '08:00:00' };

function toMinutes(s) { const p = String(s || '00:00:00').split(':'); return (parseInt(p[0], 10) * 60) + parseInt(p[1] || '0', 10); }

const out = [];
const skipped = [];

leads.forEach(function (l) {
  const w = byCountry[l.country_code] || DEFAULT;
  const tz = w.timezone || 'Asia/Dubai';
  const local = DateTime.now().setZone(tz);
  const mins = (local.hour * 60) + local.minute;
  const qs = toMinutes(w.quiet_hours_start);
  const qe = toMinutes(w.quiet_hours_end);
  // Quiet hours wrap midnight (22:00 -> 08:00), so start > end means the window spans days.
  const inQuiet = (qs > qe) ? (mins >= qs || mins < qe) : (mins >= qs && mins < qe);
  if (inQuiet) {
    skipped.push({ lead_id: l.id, reason: 'quiet_hours', local_time: local.toFormat('HH:mm'), tz: tz });
    return;
  }
  const convos = Array.isArray(l.conversations) ? l.conversations : [];
  const transcript = convos.slice()
    .sort(function (a, b) { return (a.turn_number || 0) - (b.turn_number || 0); })
    .map(function (c) { return (c.direction === 'outbound' ? 'A: ' : 'L: ') + (c.message || ''); })
    .join('\n');
  out.push({ json: {
    lead_id: l.id,
    first_name: l.first_name || '',
    whatsapp_number: l.whatsapp_number,
    language: l.language || 'en',
    country_code: l.country_code || null,
    timezone: tz,
    local_time: local.toFormat('HH:mm'),
    property_interest: l.property_interest || '',
    area_of_interest: l.area_of_interest || '',
    budget_max: (l.budget_max == null ? '' : l.budget_max),
    currency: l.currency || '',
    timeline: l.timeline || '',
    silent_since: l.updated_at,
    turn_count: convos.length,
    transcript: transcript
  } });
});

// Attach the skip tally to every surviving item so the run log can report it.
out.forEach(function (o) { o.json.skipped_quiet_hours = skipped.length; });

// Zero nudgeable leads => zero items => the whole branch no-ops silently, exactly like the
// close branch does on a quiet hour. Leads skipped for quiet hours are simply retried next hour.
return out;

return $input.all().map(function (item) {
  const l = item.json;
  const system = [
    'You write ONE short WhatsApp follow-up to a real-estate lead in MENA who stopped replying about 24 hours ago. If they stay silent the agency closes the conversation.',
    'Write ONLY the message text. No JSON, no quotes, no preamble, no sign-off.',
    'LANGUAGE: write in the lead language given below (ar | en | fr | mixed). ar = natural Arabic in the country register (Gulf / Levant / Egyptian).',
    'CULTURAL (non-negotiable): no religious phrasing, and never in-sha-Allah for timing. Neutral greeting (marhaba / Hello / Bonjour). Currency is NEVER assumed. Formality by tone: casual or short history => informal Arabic anta; formal or business => hadretak; unsure => lean respectful.',
    'CONTENT: reference the specific thing they were actually discussing (area, property type, budget only if they stated one). Ask ONE light question that makes replying easy. Never invent facts. No pressure, no hype, no discounts, no promises about timing, and do NOT say the conversation is about to be closed.',
    'LENGTH: under 300 characters. At most one tasteful emoji, and only if the transcript is casual.'
  ].join('\n');
  const budget = (l.budget_max === '' || l.budget_max === null)
    ? '(none given)'
    : (l.budget_max + ' ' + (l.currency || '(currency not stated)'));
  const user = [
    'Lead: ' + (l.first_name || '(no name)'),
    'Language: ' + l.language,
    'Country: ' + (l.country_code || '(unknown)'),
    'Looking for: ' + (l.property_interest || '(unspecified)'),
    'Area: ' + (l.area_of_interest || '(unspecified)'),
    'Budget: ' + budget,
    'Timeline: ' + (l.timeline || '(none given)'),
    '',
    'Conversation so far (A = agency, L = lead):',
    (l.transcript || '(only the first acknowledgment was sent; the lead never replied)'),
    '',
    'Write the follow-up message now.'
  ].join('\n');
  const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 200, system: system, messages: [{ role: 'user', content: user }] };
  return { json: Object.assign({}, l, { anthropic_body: body }) };
});

const sources = $('Build Nudge Request').all();
return $input.all().map(function (item, i) {
  const src = (sources[i] && sources[i].json) ? sources[i].json : {};
  let text = '';
  let degraded = true;
  try {
    const data = (item.json && item.json.body) ? item.json.body : item.json;
    if (data && Array.isArray(data.content)) {
      const tb = data.content.find(function (b) { return b && b.type === 'text' && b.text; });
      if (tb) { text = String(tb.text).trim(); if (text) degraded = false; }
    }
  } catch (e) {}
  if (!text) {
    // Static fallback, used only when the model call failed or returned nothing.
    const nm = src.first_name ? (' ' + src.first_name) : '';
    const tmpl = {
      ar: 'مرحبا' + nm + '، حابين نطمن عليك بخصوص بحثك عن العقار. لسا عم تدور؟ نحنا جاهزين نساعدك وقت ما تكون جاهز.',
      fr: 'Bonjour' + nm + ', toujours a la recherche ? Nous restons a votre disposition quand vous voulez.',
      en: 'Hi' + nm + ', just checking in on your property search. Still looking? Happy to help whenever you are ready.'
    };
    text = tmpl[src.language] || tmpl.en;
  }
  if (text.length > 300) text = text.slice(0, 297) + '…';
  return { json: Object.assign({}, src, { nudge_message: text, nudge_degraded: degraded }) };
});
